import { Injectable, Logger } from '@nestjs/common';
import { Cron } from '@nestjs/schedule';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { InjectQueue, Processor, Process } from '@nestjs/bull';
import { Queue, Job } from 'bull';
import { Account } from './entities/account.entity';
import { LedgerEntry } from './entities/ledger-entry.entity';

interface ReconcileJobData {
  accountId: string;
  balance: number;
  cutOff: string;
}

@Injectable()
export class ReconciliationService {
  private readonly logger = new Logger(ReconciliationService.name);

  constructor(
    @InjectRepository(Account)
    private readonly accountRepo: Repository<Account>,
    @InjectQueue('reconciliation-queue')
    private readonly reconciliationQueue: Queue<ReconcileJobData>,
  ) {}

  @Cron('0 2 * * *')
  async runReconciliation(): Promise<void> {
    // Bound every SUM by this single timestamp so ledger rows written
    // after the run starts (in-flight transactions) are never counted
    // as drift.
    const cutOff = new Date();

    // FULL SCAN: loads every account with no activity filter — there is
    // no WHERE narrowing this to accounts that changed since the last run.
    const accounts = await this.accountRepo.find();

    this.logger.log(
      `Enqueuing ${accounts.length} accounts for reconciliation as of ${cutOff.toISOString()}`,
    );

    for (const account of accounts) {
      await this.reconciliationQueue.add('reconcile-account', {
        accountId: account.id,
        balance: account.balance,
        cutOff: cutOff.toISOString(),
      });
    }
  }
}

@Processor('reconciliation-queue')
export class ReconciliationProcessor {
  private readonly logger = new Logger(ReconciliationProcessor.name);

  constructor(
    @InjectRepository(LedgerEntry)
    private readonly ledgerRepo: Repository<LedgerEntry>,
  ) {}

  // SINGLE WORKER: concurrency=1 so two workers can never pick up the
  // same account and race each other into a double-fix.
  @Process({ name: 'reconcile-account', concurrency: 1 })
  async handleReconcile(job: Job<ReconcileJobData>): Promise<void> {
    const { accountId, balance, cutOff } = job.data;

    // PER-ACCOUNT RECOMPUTE: sum every ledger row for this account up to
    // the cut-off.
    const result = await this.ledgerRepo.query(
      `SELECT COALESCE(SUM(amount), 0) AS total
       FROM ledger
       WHERE account_id = $1 AND created_at <= $2`,
      [accountId, cutOff],
    );
    const computedBalance = Number(result[0].total);

    // DRIFT CHECK + COMPENSATION
    const drift = computedBalance - balance;

    if (drift !== 0) {
      await this.ledgerRepo.insert({
        accountId,
        amount: -drift,
        type: 'RECONCILE_ADJUSTMENT',
        createdAt: new Date(),
      });

      this.logger.warn(
        `Account ${accountId} drifted by ${drift}; inserted compensating entry`,
      );
    }
  }
}
